	DELVELOG_LBL_KEY = "Schlüssel",
	DELVELOG_TOTAL_TIME = "Gesamtzeit:",
	INFO_DRAWER_BODY_DELVELOG = "Das Tiefen-Log erfasst jede Midnight-Tiefe, die du mit diesem Charakter abschließt. Klicke auf eine Tiefe, um die letzten Läufe aufzuklappen. Jeder Lauf zeigt Stufe, Clearzeit, Tode, ob du einen Restored Coffer Key genutzt hast, und den Endboss. Das Tracking läuft im Hintergrund; dieser Tab muss nicht offen sein.",
	TAB_WORLD = "Void & Rituals",
	TAB_EVENTS = "Ereignisse",
	EVENTS_SUBTITLE = "Alle Weltereignisse von Midnight: was gerade läuft und was in den nächsten 24 Stunden kommt. Klicke ein aktives Ereignis für eine Route an; fahre mit der Maus darüber für Infos und Belohnungen.",
	EVENTS_NONE = "Momentan keine Weltereignisse sichtbar — der Planer lädt vielleicht noch. Versuche es in ein paar Sekunden erneut.",
	WORLD_EVENTS_HEADER = "Weltereignisse",
	WORLD_EVENTS_NOW = "Jetzt",
	WORLD_EVENTS_SOON = "Demnächst",
	WORLD_EVENT_NOW_FMT = "%s — %s",
	WORLD_EVENT_SOON_FMT = "%s (%s) — in %s",
	EVENT_INFO_REWARD_LABEL = "Belohnungen:",
	EVENT_INFO_CLICK_HINT = "Klicken für eine Route.",
	EVENT_INFO_STORMARION_DESC = "Tower-Defense in Voidstorm an der Stormarion Citadel — beginnt alle 30 Minuten. Wehrt die Wellen zusammen mit allen in der Zone ab.",
	EVENT_INFO_STORMARION_REWARD = "Jeder abgeschlossene Durchlauf: ein Victorious Stormarion Cache (Stormarion Cores, Voidlight Marl, Gold). Dein erster Abschluss jeder Woche gibt den größeren Pinnacle Cache und Ruf bei The Singularity. Beide Truhen können das Reittier Contained Stormarion Defender und das Haustier Kai droppen.",
	EVENT_INFO_HARANIR_DESC = "Ein ruhigeres Story-Ereignis in Harandar. Nimm die Wochenquest 'Lost Legends' an, wähle ein Relikt und spiele seine Lore-Questreihe (solo machbar).",
	EVENT_INFO_HARANIR_REWARD = "Eine Wochentruhe, Hara'ti-Ruf und ein Einrichtungsstück passend zu deinem Relikt. Findest du jedes Lore-Objekt in den Relikt-Geschichten, bekommst du den Titel 'Chronicler of the Haranir'.",
	EVENT_WEEKLY_DONE = "Wochenquest erledigt",
	EVENT_WEEKLY_TURNIN = "Wochenquest: abgeben!",
	EVENT_WEEKLY_ACTIVE = "Wochenquest: läuft",
	EVENT_WEEKLY_TODO = "Wochenquest verfügbar",
	EVENT_WEEKLY_LABEL = "Wochenquest:",
	MODEL_PREVIEW_HINT = "Ziehen zum Drehen · scrollen zum Zoomen",
	MODEL_PREVIEW_SPIN = "Drehen",
	MODEL_PREVIEW_RESET = "Zurücksetzen",
	MODEL_PREVIEW_REWARDS_HINT = "Umschalt-Klick: Belohnungen ansehen",
	WORLD_SUBTITLE = "Der wöchentliche Weltinhalt von Midnight in Quel'Thalas. In einer Zone ist eine Ritualstätte aktiv, in einer anderen greift die Leere an — beide teilen den Basar-Hub, Feldauszeichnungen und Ansehen.",
	INFO_DRAWER_BODY_WORLD = "Void & Rituals vereint die zwei wechselnden Weltsysteme von Midnight. Ritualstätten: störe die aktive Stätte (violettes Kartensymbol) am Obelisken. Void-Angriffe: schließe Void-Schläge in der aktiven Zone ab, um einen Void-Einfall auszulösen. Beide geben Feldauszeichnungen, füllen deine Schatzkammer-Weltzeile und speisen das gemeinsame Ritualstätten-Ansehen. Beide Wochenquests gibt es am Basar-Hub in Silbermond.",
	TAB_REFERENCE = "Grundlagen",
	REF_PANEL_INTRO = "Einfache Erklärungen für Endgame-Systeme. Weitere Themen kommen hier dazu.",
	INFO_DRAWER_BODY_REFERENCE = "Einsteigerfreundliche Ratgeber: Crests, wo du ausgibst und Warband-Boni. Weitere Themen (u. a. Berufe) folgen.",
	TAB_SMC = "Silvermoon City",
	TAB_PROFESSIONS = "Berufe",
	TAB_GUIDE = "Leveling (80-90)",
	TAB_MACROS = "Makros",
	TAB_CONSUMABLES = "Verbrauchsmaterial",
	TAB_ACADEMY = "Rollenakademie",
	TAB_TOOLBOX = "Werkzeugkiste",
	-- Patch 12.0.7 Kodex-Artikel
	CODEX_127_SHOWDOWNS_TITLE = "Showdowns: Naigtal & Val (12.0.7)",
	CODEX_127_SHOWDOWNS_BODY = "Ein Portal im Voidstorm (Howling Ridge) oder das dauerhafte Portal im Basar von Silbermond führt in eine von zwei Void-Welten, die jede Woche wechseln: das pilzbewachsene Naigtal oder das eisige Val. Beide bieten Weltquests, Rares, Zonen-Events und einen Weltboss (Nexus-Captain Leth'ir / Imperator Pertinax). Die Showdown-Weekly gewährt einen Riftstalker's Cache und zählt für die World-Reihe der Großen Schatzkammer. Optional erhöht die Heroic World Tier Schwierigkeit und Belohnungen — Wahl am Portal. Start bei Riftblade Maella in Silbermond. In Saison 2 ist das Aufhol-Content: gut für Twinks und frische Charaktere auf Stufe 90, nicht für deine beste Ausrüstung.",
	CODEX_127_SPOREFALL_TITLE = "Sporefall-Schlachtzug (12.0.7)",
	CODEX_127_SPOREFALL_BODY = "Ein-Boss-Schlachtzug in Harandar: Rotmire, ein Pilzriese. Es ist ein Schlachtzug der Saison 1: Seine Ausrüstung (LFR 259 / Normal 272 / Heroisch 285 / Mythisch 298) liegt unter derselben Schwierigkeit im Schlachtzug der Saison 2, du gehst also für das Reittier und die Optik hin, nicht für Upgrades. Mythisch ist flexibel mit 15-25 Spielern. Hol dir einmal pro Woche (pro Account) auf beliebiger Schwierigkeit einen Delicious Sporesnack — vier davon kombinierst du zum Reittier Luminous Sporeglider.",
	CODEX_127_FOLIO_TITLE = "Omnium Folio & Runen (12.0.7)",
	CODEX_127_FOLIO_BODY = "Neues Machtsystem ohne Ausrüstungsplatz. Freischaltung über die Sunstrider-Omnium-Questreihe mit Magister Umbric und Großmagister Rommath auf Quel'Danas. Jede Woche gewährt die Quest 'Seeking Knowledge' einen Mote of Omnial Inquiry, der eine von fünf Runenreihen öffnet; Runen lassen sich außerhalb des Kampfes frei tauschen.",
	CODEX_127_TIMEWAYS_TITLE = "Turbulent Timeways V (30. Jun - 11. Aug)",
	CODEX_127_TIMEWAYS_BODY = "Zeitwanderungs-Marathon mit sechs Dragonflight-Dungeons. Vier Dungeons pro Woche bringen den Mastery-Buff der Woche; Mastery in vier verschiedenen Wochen sichert das Reittier Spawn of Vyranoth.",
	CODEX_127_RITUALRENOWN_TITLE = "Ritual Sites Renown (12.0.5)",
	CODEX_127_RITUALRENOWN_BODY = "Ritual Sites haben einen accountweiten Renown-Pfad (8 Ränge) im Journeys-Fenster. Höhere Ränge machen jede Site reicher: heilende Regeneration Orbs, dann seltene Gegner (Rang 4), Buff-Schreine (Rang 5), größere Schätze (Rang 7) und seltene Elites (Rang 8) — alle mit zusätzlichen Spoils. Außerdem schaltet er Silbermond-Händlerwaren frei: Void-Wohnungsdeko (Rang 3, Rae'ana), Haustiere (Rang 6, Sergeant Vornin) und das Reittier Void-Touched Hawkstrider (Rang 8, Sergeant Vornin). Jede Belohnung ist Warband-weit, dein Fortschritt zählt also für den ganzen Account. Klicke die leuchtenden Loa-Schreine in einer Site an für einen 60-minütigen Werte-Buff (z. B. +10% kritische Trefferchance).",
	TAB_BETA_BADGE = "Beta",
	TAB_BETA_TOOLTIP_TITLE = "In Entwicklung",
	TAB_BETA_TOOLTIP_BODY = "Dieser Tab ist frühe Beta — Inhalt ist unvollständig, kann sich oft ändern und ist noch nicht produktionsreif.",
	TAB_ADDONS = "Add-ons",
	SEARCH_CHAT_TAB_ACADEMY = "Geöffneter Tab: Rollenakademie",
	ACADEMY_SUBTITLE = "Kurzer Meisterkurs zum Tanken und Heilen in Gruppen – Denkweise, Vorbereitungs-Checkboxen und ein sanfter Aufstieg in Dungeons. Kein Parse-Leitfaden.",
	ACADEMY_TRACK_TANK = "Tank-Spur",
	ACADEMY_TRACK_HEAL = "Heal-Spur",
	ACADEMY_TRACK_DPS = "DPS-Spur",
	-- „Berufe“ ist der Name, den dieselbe Datei dem Tab gibt (TAB_PROFESSIONS) — der
	-- Hinweis muss dorthin zeigen, wo der Spieler wirklich klicken soll.
	NAV_WHERE_PROFACADEMY = "in Berufe",
	ACADEMY_CLASS_FMT = "Angemeldet: %s - %s (öffne Makros / Verbrauchsmaterialien / Anleitungen in der Seitenleiste)",
	ACADEMY_CLASS_OPEN_CHAT_FMT = "Makros geöffnet für %s - %s. Schau auch bei Verbrauchsmaterialien nach Flaschen und Töpfen.",
	ACADEMY_PREF_TITLE = "Checkliste vor dem Start (abhaken, wenn du bereit bist)",
	ACADEMY_PREF_HINT = "Häkchen werden in deinen Einstellungen gespeichert. Öffne beim Vorbereiten die passende Registerkarte in der Seitenleiste.",
	ACADEMY_PREF_TANK_INTERRUPT = "Unterbrechungsmakro auf meiner Leiste (Registerkarte „Makros“)",
	ACADEMY_PREF_TANK_DEFENSIVE = "Eine bereite Defensive (Anleitungen -> Defensiven oder In Gruppen)",
	ACADEMY_PREF_TANK_CONSUMABLES = "Flasche/Topf bereit (Registerkarte „Verbrauchsmaterialien“)",
	-- ⚠️ Stand hier als „Verspottungsschlüssel“. Ein Schlüssel schließt eine Tür; eine
	-- Taste sitzt auf der Tastatur — für einen deutschen Spieler war das schlicht das
	-- falsche Wort. Dieselbe Verwechslung steckt noch an vier Stellen im Layout- und
	-- Guide-Text dieser Datei; die gehören nicht zur Akademie und bleiben vorerst
	-- stehen, damit diese Änderung überprüfbar bleibt.
	ACADEMY_PREF_TANK_TAUNT = "Ich kenne meine Spott-Taste (einmal am Dummy getestet)",
	ACADEMY_PREF_HEAL_MACROS = "Mouseover-/Fokusheilungsmakros (Registerkarte „Makros“)",
	ACADEMY_PREF_HEAL_DEFENSIVE = "Persönliche Defensive am Balken (Guides -> Defensiven oder In Gruppen)",
	ACADEMY_PREF_HEAL_CONSUMABLES = "Manatopf/Flasche (Registerkarte „Verbrauchsgüter“)",
	ACADEMY_PREF_HEAL_PRACTICE = "Mouseover-Heilung einmal an einem Freund geübt",
	ACADEMY_PREF_DPS_ROTATION = "Hauptfähigkeiten auf gut erreichbaren Tasten",
	ACADEMY_PREF_DPS_INTERRUPT = "Mein Unterbrechen ist gebunden (einmal am Dummy getestet)",
	ACADEMY_PREF_DPS_DEFENSIVE = "Eine persönliche Defensive auf meiner Leiste",
	ACADEMY_PREF_DPS_COOLDOWNS = "Schadens-Cooldowns gebunden (nicht irgendwo auf der Leiste verloren)",
	ACADEMY_TANK_INTRO_TITLE = "Tank-Denkweise",
	ACADEMY_TANK_INTRO_BODY = "Deine Aufgabe ist, das Tempo vorzugeben und die Aufmerksamkeit zu halten – nicht, die Schadensanzeige anzuführen.\n\nEin ruhiger Pull schlägt eine perfekte Rotation bei einer toten Gruppe. Sag Pulls laut, wenn es hilft: „Pull in 3“.",
	ACADEMY_TANK_PULL_TITLE = "Während eines Pulls (erste 10 Sekunden)",
	ACADEMY_TANK_PULL_BODY = "1. Schnapp dir das Rudel (Verspottung/Drohung).\n2. Dreh Gegner von der Gruppe weg, wenn du kannst.\n3. Nutze eine Defensive bei Schadensspitzen – die zweite für „Oh nein“ aufheben.\n4. Unterbrich den Cast, der am meisten wehtut (oft Heilung oder großer Treffer).\n\nDu musst nicht jede Fähigkeit sofort auf Cooldown haben.",
	ACADEMY_TANK_WIPE_TITLE = "Wenn es schief geht",
	ACADEMY_TANK_WIPE_BODY = "Ein Wipe ist Daten, kein Urteil. Frag: „War ich zu weit vorn?“ oder „Habe ich eine Defensive gespart?“\n\nReparieren, essen, nochmal versuchen.",
	ACADEMY_TANK_DUNGEON_TITLE = "Dein erster Dungeon (normal)",
	ACADEMY_TANK_DUNGEON_BODY = "Starte normal mit Freunden oder Gildenmitgliedern, wenn du kannst. Pull langsam – zwei kleine Packs schlagen eine große Kette.\n\nAchte auf das Mana des Heilers; Pause zwischen Pulls. CC oder „noch kein großer Pull“ zu fragen ist ok.",
	ACADEMY_TANK_RAID_TITLE = "Schlachtzüge und LFR (später)",
	ACADEMY_TANK_RAID_BODY = "LFR ist der sanfte Einstieg in Schlachtzüge: verzeihend, viele Heiler. Fokus auf Boss-Taunt-Timing und am richtigen Fleck stehen.\n\nMythisches Schlachtzugs-Tanken ist nicht der nächste Schritt – erst Komfort in heroisch/LFR.",
	ACADEMY_TANK_CHAT_TITLE = "Party-Chat",
	ACADEMY_CHAT_HINT = "Klick eine Zeile oder das Kopiersymbol, dann Strg+C für den Party-Chat.",
	ACADEMY_CHAT_COPY_TIP = "Diese Zeile markieren (Strg+C)",
	ACADEMY_TANK_CHAT_BODY = "\"Tank lernt noch – bitte langsam.\"\n\"Pull in 3...\"\n\"Kurz Pause für Mana.\"\n\"Kick auf [Zaubername] – den nächsten übernehme ich.\"\n\"Noch ein Versuch – den Pull kenne ich jetzt.\"",
	ACADEMY_TANK_LADDER_TITLE = "Angstleiter (empfohlene Reihenfolge)",
	ACADEMY_TANK_LADDER_BODY = "1. Welt-Elite mit einem Freund\n2. Tiefen (kleinere Instanz – Tab Tiefen)\n3. Normaler Dungeon mit Leuten, denen du vertraust\n4. Heroisch / LFR, wenn du dich wohlfühlst\n\nBleib bei jedem Schritt, bis er sich langweilig statt beängstigend anfühlt. Dann geh eine Stufe höher.",
	ACADEMY_TANK_BOTH_TITLE = "Auch heilen lernen?",
	ACADEMY_TANK_BOTH_BODY = "Super – aber wähle in Dungeons eine Weile eine Hauptrolle. Übe die andere in Tiefen oder der offenen Welt.\n\nTank und Heal im selben M+-Pug verdoppelt Stress; eine Rolle zuerst sicher machen baut Vertrauen für die zweite.",
	ACADEMY_HEAL_INTRO_TITLE = "Heal-Mindset",
	ACADEMY_HEAL_INTRO_BODY = "Du bist nicht dafür da, dass alle dauernd 100 % HP haben.\n\nDeine Aufgabe ist Triage: Tank am Leben halten, wer gleich stirbt retten, dann der Rest. Etwas Schaden ist normal – Panik-Overheal leert Mana.",
	ACADEMY_HEAL_TRIAGE_TITLE = "Triage (Wer zuerst?)",
	ACADEMY_HEAL_TRIAGE_BODY = "1. Du (wenn du stirbst – toter Heiler heilt niemanden)\n2. Tank (solange die Gegnergruppe noch an ihm dran ist)\n3. Jeder unter ~40 % oder mit einem tödlichen Debuff\n4. Alle anderen mit effizienten Heilungen\n\nGroße Heilung nach großem Schaden; kleine Heilungen zwischen Ereignissen.",
	ACADEMY_HEAL_WIPE_TITLE = "Wenn es schief geht",
	ACADEMY_HEAL_WIPE_BODY = "„Hätte ich den Tank retten können?“ ist die nützliche Frage – nicht „Warum stand DPS im Feuer?“\n\nWar Mana leer, nutz beim nächsten Mal effizientere Zauber. Ein Wipe heißt nicht, dass du nicht heilen kannst.",
	ACADEMY_HEAL_DUNGEON_TITLE = "Dein erster Dungeon (normal)",
	ACADEMY_HEAL_DUNGEON_BODY = "Sag der Gruppe, dass du lernst. Bleib in Reichweite des Tanks; lass DPS einen Kratzer nehmen, bevor du Mana verbrennst.\n\nZwischen Pulls: trinken, buffen, atmen. „oom, 5 sec“ zu sagen ist ok.",
	ACADEMY_HEAL_RAID_TITLE = "Schlachtzüge und LFR (später)",
	ACADEMY_HEAL_RAID_BODY = "LFR: Schlachtzugsweiter Schaden ist nach einem Wipe vorhersehbar. Lerne den Kampf-Timer, nicht die Balken jedes Spielers.\n\nSchlachtzugsheilungen verwenden die gleiche Triage – Tank- und Schlachtzugs-Abklingzeitfenster zuerst.",
	ACADEMY_HEAL_CHAT_TITLE = "Party-Chat",
	ACADEMY_HEAL_CHAT_BODY = "\"Heiler lernt noch – ich sage Bescheid, wenn mein Mana knapp wird.\"\n\"Tank hat Priorität – schrei, wenn du eine Verschnaufpause brauchst.\"\n\"Große Heilung für dich – achte auf deine Gesundheit.\"\n\"Oom – 5 Sekunden Pause zwischen den Pulls.\"\n\"Das war mein Fehler – beim nächsten Pull halte ich mehr für den Tank zurück.\"",
	ACADEMY_HEAL_LADDER_TITLE = "Angstleiter (empfohlene Reihenfolge)",
	ACADEMY_HEAL_LADDER_BODY = "1. Heile einen Freund in der offenen Welt\n2. Tiefen mit kleiner Gruppe\n3. Normaler Dungeon mit geduldigen Freunden\n4. Schlachtzug LFR / heroisch, wenn bereit\n\nTiefen sind der sanfteste Schritt in instanzierten Content.",
	-- Die fünf fehlenden Heal-Kapitel, nachgetragen 19 Aug 2026. Sie standen bisher
	-- auf Englisch mitten zwischen den deutschen — dieselbe Lücke wie bei den
	-- Dungeon-Tipps, und aus demselben Grund: die Kapitel kamen nach der
	-- Übersetzungsrunde dazu.
	ACADEMY_HEAL_MANA_TITLE = "Mana und Effizienz",
	ACADEMY_HEAL_MANA_BODY = "Mana ist deine eigentliche Lebensanzeige. Ist es leer, kannst du gar nicht mehr heilen.\n\nNimm billige, schnelle Heilungen für kleine Diller; heb die großen, teuren für echte Notfälle auf. Nicht jeder muss auf voll stehen – lass die Leute ruhig auf 80 % laufen.\n\nTrink zwischen jedem Pull. „Oom, 5 Sek“ zu sagen ist normal und professionell.",
	ACADEMY_HEAL_POSITION_TITLE = "Wo du stehst",
	ACADEMY_HEAL_POSITION_BODY = "Bleib in Reichweite der ganzen Gruppe, aber nicht oben auf dem Boss. Eine hintere Ecke mit Sicht auf alle schlägt Ankleben am Tank.\n\nAusweichen musst du trotzdem. Ein toter Heiler heilt niemanden – geh aus dem Dreck raus, auch wenn es eine halbe Sekunde Zauberzeit kostet.\n\nAcht auf Sichtlinie: durch eine Wand oder Säule heilst du niemanden.",
	ACADEMY_HEAL_COOLDOWNS_TITLE = "Heb deine großen Cooldowns auf",
	ACADEMY_HEAL_COOLDOWNS_BODY = "Deine großen Heil-Cooldowns sind für großen, geplanten Schaden – den schlachtzugsweiten Schlag eines Bosses – nicht für zufällige Kratzer.\n\nEinen Cooldown den ganzen Kampf „für alle Fälle“ festzuhalten verschenkt ihn. Ein Cooldown, der zu 90 % im richtigen Moment kommt, schlägt einen, der nie kommt.\n\nTipp /mh healcds für die Cooldowns deiner Spezialisierung und wofür du jeden aufheben solltest.",
	ACADEMY_HEAL_MISTAKES_TITLE = "Typische Anfängerfehler",
	ACADEMY_HEAL_MISTAKES_BODY = "1. Auf eine Lebensanzeige starren, während drei andere fallen\n2. In Panik auf 100 % hochheilen und dabei Mana leeren\n3. Im Dreck stehen, weil du auf die Balken schaust\n4. Die eigenen Cooldowns nie drücken\n5. Schaden weganheilen, statt um eine Unterbrechung zu bitten\n\nNimm dir pro Lauf einen davon vor – nicht alle fünf auf einmal.",
	ACADEMY_HEAL_CONFIDENCE_TITLE = "Es ist okay, jemanden zu verlieren",
	ACADEMY_HEAL_CONFIDENCE_BODY = "Irgendwann stirbt jemand unter deiner Aufsicht. Jeder Heiler, den es gibt, hat Leute sterben lassen – so lernt man, wo die Grenzen liegen.\n\nEin Tod ist kein Wipe, und ein Wipe ist kein Urteil über dich. Merk dir die eine Sache, die du anders machen würdest, und dann lass es gut sein.\n\nGruppen erinnern sich an einen ruhigen Heiler, der redet, weit eher als an einen perfekten.",

	ACADEMY_HEAL_BOTH_TITLE = "Auch Tank oder DPS lernen?",
	ACADEMY_HEAL_BOTH_BODY = "Nutze die Tank-Spur fürs Dungeon-Queueing; heile weiter in Tiefen, bis Tanken vertraut wirkt.\n\nZwei Rollen in einer Woche in Pugs ist viel – eine Rolle als „Haupt“ nimmt die Angst.",

	-- Die komplette DPS-Spur, nachgetragen 19 Aug 2026. Sie existierte bisher nur auf
	-- Englisch: die Rolle kam als ganzer Stapel dazu, lange nachdem Tank und Heal
	-- übersetzt worden waren. Ton und Anrede von den beiden anderen Spuren übernommen,
	-- nicht neu erfunden.
	ACADEMY_DPS_INTRO_TITLE = "DPS-Denkweise",
	ACADEMY_DPS_INTRO_BODY = "Deine Aufgabe ist Schaden – aber ein toter DPS macht null. Am Leben bleiben und Mechaniken erledigen kommt zuerst, Schaden danach.\n\nDu musst nicht oben auf der Anzeige stehen. Gleichmäßiger Schaden, während du deine Arbeit machst, schlägt riesige Zahlen mit einem Tod dahinter.",
	ACADEMY_DPS_ROTATION_TITLE = "Priorität statt fester Rotation",
	ACADEMY_DPS_ROTATION_BODY = "Die meisten Spezialisierungen bauen eine Ressource auf und geben sie wieder aus. Halt Aufbau und Ausgabe im Fluss; lauf nicht ins Ressourcen-Cap und lass keine DoTs oder Buffs auslaufen.\n\nEin oder zwei Tasten zur richtigen Zeit schlagen fünf im Blindflug. Lern die Priorität, keine auswendige Reihenfolge.",
	ACADEMY_DPS_COOLDOWNS_TITLE = "Bring deine Cooldowns in Reihe",
	ACADEMY_DPS_COOLDOWNS_BODY = "Deine Schadens-Cooldowns sind der größte Teil deines Schadens. Sie zu drücken, sobald sie bereit sind, schlägt das Aufheben für einen „perfekten“ Moment, der nie kommt.\n\nBeim Boss: entweder gleich damit eröffnen oder für die Phase aufheben, auf die es ankommt. Dein Werkzeugkasten oben listet sie für deine Spezialisierung auf.",
	ACADEMY_DPS_MECHANICS_TITLE = "Mechaniken schlagen Schaden",
	ACADEMY_DPS_MECHANICS_BODY = "Geh aus dem Dreck raus, auch wenn es einen Zauber kostet. Ein Stapel vermeidbarer Schaden wipet die Gruppe schneller als niedriger DPS es je könnte.\n\nGierig ist, für einen Zauber mehr im Feuer stehen zu bleiben. Gut ist, sich eine halbe Sekunde neu zu stellen und den Rest noch drücken zu können.",
	ACADEMY_DPS_UTILITY_TITLE = "Du bist kein Schadensautomat",
	ACADEMY_DPS_UTILITY_BODY = "Unterbrich gefährliche Zauber, nutz deine Kontrolle, und drück deine persönliche Defensive, wenn du einen großen Treffer kassierst.\n\nEin DPS, der unterbricht und überlebt, ist weit mehr wert als einer, der nur Zahlen pumpt.",
	ACADEMY_DPS_MISTAKES_TITLE = "Typische Anfängerfehler",
	ACADEMY_DPS_MISTAKES_BODY = "1. Auf Cooldowns sitzen bleiben, „nur für den Fall“\n2. Ins Ressourcen-Cap laufen (verschenkter Aufbau)\n3. Für einen Zauber mehr im Dreck stehen bleiben\n4. Nie unterbrechen, nie Utility nutzen\n5. Im Tunnelblick Schaden fahren, während dein Leben nach unten geht\n\nNimm dir pro Lauf einen davon vor – nicht alle fünf auf einmal.",
	ACADEMY_DPS_PRACTICE_TITLE = "Üben am Dummy",
	ACADEMY_DPS_PRACTICE_BODY = "Zwei Minuten auf eine Übungspuppe: halt deine Ressource im Fluss, web deine Cooldowns ein, und schau, was dabei ausläuft.\n\nDanach Tiefen, danach normale Dungeons. Du brauchst zum Anfangen keine perfekte Rotation – du musst weiterdrücken und am Leben bleiben.",
	ACADEMY_DPS_BOTH_TITLE = "Über Tank oder Heal nachgedacht?",
	ACADEMY_DPS_BOTH_BODY = "Du kennst die Kämpfe schon vom DPS-Platz aus, und das ist der größte Teil der Arbeit. Tanken bringt dir sofortige Dungeon-Warteschlangen; Heilen kostet die meisten Nerven, ist aber am gefragtesten.\n\nProbier die neue Rolle erst in einer Tiefe oder einem Gefolgsleute-Dungeon aus, wo niemand auf dich wartet. Bleib danach eine Weile bei einer Rolle als Haupt, statt in jedem Pug zu wechseln.",
	INFO_DRAWER_BODY_ACADEMY = "Rollenakademie: Tank-/Heal-Spuren, Checkliste, Dungeon- vs. Schlachtzugsnotizen und Party-Chat-Zeilen. Leveling Guides ergänzt pro Rolle den Tab „In Gruppen“. In der Seitenleiste: Makros, Verbrauchsmaterialien, Guides und Tiefen.",
