	KEYBIND_ROLE_COOLDOWN = "Cooldown-Leiste",
	LAYOUT_PROTOTYPE_SUBTITLE = "Vollständige Tastaturvorschau: Midnight-Tasten leuchten, die anderen sind ausgegraut. Fahr mit der Maus über eine Taste, um jede Belegung darauf zu sehen — ein Abzeichen +N bedeutet N zusätzliche Umschalt-/Strg-Belegungen. Tipps im Guide-Tab können hierher springen und eine Taste hervorheben.",
	LAYOUT_KEY_UNUSED_TOOLTIP = "|cff888888Wird in der Midnight-Tastenbelegung dieser Spezialisierung nicht verwendet.|r",
	LAYOUT_KEY_MODIFIER_TOOLTIP = "|cff888888Modifikatortaste – WoW verarbeitet Umschalt-/Strg-/Alt-Kombinationen getrennt von dieser Zauberkarte.|r",
	LAYOUT_KEY_NAV_TOOLTIP = "|cff888888Navigations-/Bearbeitungscluster – nicht Teil der Midnight-Tastenkarte.|r",
	LAYOUT_KEY_EMPTY_TOOLTIP = "|cffaaaaaaNoch keine Rolle für diese Taste in der aktuellen Belegung der Spezialisierung.|r",
	LAYOUT_KEY_G_OPTIONAL_TOOLTIP = "|cffaaaaaaSlot G existiert im Raster, aber dieses Team lässt ihn oft leer – optionale Belegung.|r",
	LAYOUT_KEY_ROLE_TOOLTIP_FMT = "|cffffcc00%s|r",
	LAYOUT_KEY_BIND_LAYER_FMT = "|cffe0e070%s|r — %s",
	LAYOUT_KEY_MOVEMENT_TOOLTIP = "Bewege deinen Charakter: W vorwärts, S rückwärts, A/D seitwärts, Maus zum Drehen. WoW nutzt diese Tasten standardmäßig – halte sie zum Laufen frei.",
	LAYOUT_KEY_TAB_TOOLTIP = "Tab wechselt das Ziel. WoW nutzt die Taste standardmäßig – halte Tab frei, damit du im Kampf schnell den richtigen Gegner auswählen kannst.",
	LAYOUT_KEY_PREFERRED_TOOLTIP = "Midnight-Tipp: Halte diese Taste für Zauber, Makros oder Umschalt-/Strg-Kombinationen frei – die gleiche Idee wie die leuchtenden F-Tasten auf deinen Aktionsleisten.",
	LAYOUT_LEGEND = "|cff33ff61Green|r = bewegen (W A S D).\n|cffe0e070Gold|r = Zauber und Abkürzungen auf dieser Karte.\n|cff59d9ffTab|r = Ziele schnell wechseln.\n|cff888888Grey|r = nicht auf dieser Starterkarte.",
	LAYOUT_KEY_HIGHLIGHT_FROM_GUIDE = "|cffe0e070Aus deinem Leveling-Guide geöffnet – diese Taste liegt auf der Midnight-Karte.|r",
	MODULE_PLACEHOLDER = "Modulplatzhalter – Inhalt für „%s“ wird hier bereitgestellt.",
	INFO_DRAWER_TOGGLE_SHOW = "Info",
	INFO_DRAWER_TOGGLE_HIDE = "Schließen",
	INFO_DRAWER_TITLE_FMT = "%s – Verwendung",
	INFO_DRAWER_BODY_DELVES = "Midnight-Tiefen-Kommandozentrale für deinen aktuellen Charakter.\n\nErweitere Große Schatzkammer für die wöchentliche Belohnungsverfolgung oder Midnight-Tiefen für Saisonwährungen (Restored Coffer Keys, wöchentliche Splitter, Undercoins), Reise des Tiefenforschers/Ruf und die vollständige Liste der Tiefen mit Live-Erkennung von Bountiful-Tiefen aus Karten-POIs.\n\nNavigation: Rechtsklick auf eine Zeile setzt eine Route zum Eingang. |cffffcc00TomTom (empfohlen)|r fügt den Kartenpfeil und die Wegpunktwarteschlange hinzu. |cff00ff00Reiseassistent|r (Popup, wenn du weit weg bist) zeigt Hearthstone- und Hub-Portal-Verknüpfungen an und funktioniert |cffffff00ohne|r TomTom.\n\nFind Nearest Bountiful erfordert die Installation von TomTom.",
	INFO_DRAWER_BODY_ACCOUNT = "Von diesem Add-on lokal gespeicherte charakterübergreifende Liste (gespeicherte Variablen auf deinem PC – keine Blizzard-Cloud-Synchronisierung).\n\nJede Zeile listet Schlüssel, Scherben, Undercoins, Berufsecho und eine kompakte Zusammenfassung der Großen Schatzkammer mit umfangreichen Tooltips auf; dein angemeldeter Charakter wird hervorgehoben und die Sortierung begünstigt die Nützlichkeit.\n\nZeilen werden bei Anmeldung und Währung/wöchentlichen Ereignissen aktualisiert. Beim Löschen werden nur Add-on-Snapshot-Daten entfernt – niemals dein tatsächlicher WoW-Charakter.",
	INFO_DRAWER_BODY_RARES = "Welt-Rares von Midnight nach Zone (Eversong, Zul'Aman, Harandar, Voidstorm).\n\nWähle links eine Zone. Grün = diese Woche auf DIESEM Charakter erledigt (ein Twink kann ihn noch looten); grünes UP = Vignette am Spawn (wahrscheinlich aktiv); grauer Strich = gerade nicht auf deiner Karte.\n\nNächster Rare = ein Pin; Route generieren = alle offenen Rares in TomTom. UP-Status ist ungefähr – Zonekarte öffnen oder näher heran, wenn es unsicher wirkt.",
	RARES_TITLE = "Midnight-Rares",
	RARES_SUBTITLE_FMT = "%d/%d diese Woche auf diesem Charakter erledigt · %d jetzt auf Karte sichtbar (silberner Stern)",
	RARES_EMPTY_ZONE = "Keine Rare-Liste für diese Zone.",
	RARES_BTN_NEAREST = "Nächsten Rare finden",
	RARES_BTN_ROUTE = "Route generieren",
	RARES_NEAREST_ROUTE = "|cffffff78Midnight Helper:|r TomTom: nächster Rare — %s",
	RARES_NEAREST_NONE = "Keine offenen Rares mehr in dieser Zone.",
	RARES_NEAREST_NO_TRAVEL = "Reiseassistent nicht verfügbar (Tiefen-Modul nicht geladen).",
	RARES_ROUTE_DONE_FMT = "%d/%d offene Rares in TomTom eingereiht. %s",
	RARES_ROUTE_ORDER_NEAR = "Reihenfolge: nächster zuerst, dann jeweils der nächste.",
	RARES_ROUTE_ORDER_LIST = "Reihenfolge: Listenreihenfolge (Position unbekannt).",
	RARES_TAG_UP = "UP",
	RARES_TAG_DOWN = "—",
	RARES_TIP_DONE = "Auf diesem Charakter erledigt — beim nächsten Reset wieder offen. Ein anderer Charakter von dir kann ihn noch looten.",
	RARES_TIP_UP = "Wahrscheinlich aktiv (Kartenvignette am Spawn).",
	RARES_TIP_DOWN = "Gerade nicht auf der Karte — kann später spawnen.",
	RARES_TIP_VIGNETTE_NOTE = "Kartenstatus ist ungefähr; Zonekarte öffnen oder näher heran bei Unsicherheit.",
	INFO_DRAWER_BODY_SMC = "Silvermoon City-Referenz für Midnight (Karte 2393). Dieselbe Scrollliste beginnt mit der Wöchentlich-/Hub-Checkliste, wenn Quest-IDs konfiguriert sind, und setzt sich dann in kategorisierten Pin-Rastern fort – Wesentliche Dienste, Reisen, Quest-Hubs, Berufstrainer, Sammeln und mehr.\n\nJede Standortschaltfläche legt den Benutzerwegpunkt von Blizzard fest und spiegelt ihn bei installiertem TomTom über den Slash-Befehl (/way #2393 …) wider.\n\nDer Fortschritt der Checkliste färbt zugehörige Wegpunktschaltflächen grün; aktualisiere die Quest-IDs in den Daten nach größeren Patches, wenn eine Zeile falsch aussieht.",
	INFO_DRAWER_BODY_PROFESSIONS = "Verfolgt die Wissenspunkte (KP) deiner Midnight-Berufe auf deinem aktuellen Charakter sowie Währungszeilen, wenn der Client sie liefert (Unlegierter Überfluss, Tatkraft des Handwerkers, wöchentliche Splitter von Dundun).\n\nDarunter werden in zwei Spalten Wissenssammelquests und Berufsbücher pro Beruf aufgeführt – Symbole zeigen an, ob jede Quest abgeschlossen ist. Klicke auf eine Zeile, um nur diesen Pin an TomTom zu senden (löscht andere Wegpunkte; Travel Assistant verarbeitet zonenübergreifende Sprünge, wenn TomTom geladen ist).\n\nDie Schaltflächen unten reihen alle offenen Pins ein: Schätze generieren oder Bücher generieren (den nächsten offenen zuerst, wenn deine Kartenposition verfügbar ist).",
	INFO_DRAWER_BODY_GUIDE = "Leveling-Referenzen pro Spezialisierung im Stil von Icy Veins: Werteprioritäten, Ausrüstungsauswahl, Verbrauchsmaterialien, die entsprechend dem gefiltert sind, was dein Level tatsächlich verwenden kann, optionale Zaubertipp-Zeilen und der Level-Ratgeber mit Stufen-Registerkarten für Rotation, Verteidigung und Talentfokus.\n\nWenn deine Klasse über eine Midnight-Tastenkarte verfügt (vorerst Jäger/Paladin), können Tipps eine goldene Tasten-Schaltfläche anzeigen – klicke darauf, um die Registerkarte „Layout“ zu öffnen und diese Taste auf der Tastatur hervorzuheben. Dadurch wird das Lesen (was gedrückt werden muss) mit der Platzierung (wo auf der Tastatur) verknüpft, sodass du „learning by doing“ lernst.\n\nDie globale Suchleiste versteht Guide-Suchbegriffe und kann zwischen den Midnight Helper-Registerkarten wechseln; mit der Vorschau kannst du eine andere Spezialisierung lesen, ohne dich neu einzuloggen, während „Mein Charakter“ zu deiner aktiven Spezialisierung zurückkehrt.\n\nDie Sichtbarkeit der Registerkarte „Anleitung“ folgt den Einstellungen: „Auto“ (wird bei Stufe 90+ ausgeblendet), „Immer anzeigen“ oder „Immer ausblenden“.",
	INFO_DRAWER_BODY_MACROS = "Registerkarte „Unterbrechen“: Team-Kick-Makro (Fokus zuerst). Registerkarte „Utility“: zusätzliche Makros für deine Spezialisierung (Cursor-Bodenzauber, Mouseover-Heilungen und ähnliches) aus dem Teampaket. Wähle eine Zeile, lies den Tipp und kopiere den Text.\n\nDaten können sich nach Patches ändern – melde fehlende Zauber dem Team.",
	INFO_DRAWER_BODY_ADDONS = "Hub für optionale Tools, die in Midnight Helper gebündelt sind, anstatt separate Downloads.\n\nWähle oben eine Unterregisterkarte aus – heute ist das Platynator: Wago-Link, Profil-String-Import und die visuelle Galerie von MF Platynator.\n\nZusätzliche Partnerpanels werden hier automatisch registriert, wenn zukünftige Module ausgeliefert werden.",
	ABOUT_WINDOW_TITLE = "Über Midnight Helper",
	ABOUT_VERSION_FMT = "Installierte Version: |cffffcc00%s|r",
	ABOUT_WINDOW_BODY = "Autoren: TwelveInchy & Claude\n\nDein All-in-one-Begleiter für Midnight, aufgeteilt in vier Räume — Me, Codex, Tools und Settings. Hefte Favoriten unter die Suchleiste und tippe, um überallhin zu springen. Mit Diese Woche, Delves & Vault, Delve- und Ritual-Coaches, dem Berater für Verzauberungen & Edelsteine, Account-Snapshot, Codex-Guides, Berufen und integrierten Addon-Tools — EN / NL / DE / FR / ES / PT / IT.\n\nDanke an die Addons und Guides, an denen wir unsere Fakten geprüft haben: DBM (Boss-Fähigkeiten und Zauber-IDs), HandyNotes_Midnight (Fundorte von Rares und Schätzen), GTFO (Zauber-IDs von Gefahren), RareScanner (Umgang mit Vignetten) sowie Wowhead, Icy Veins, Method und wowcarry. IDs und Zahlen sind für uns Hinweise, die wir, wo immer es geht, am Spiel selbst prüfen; Code aus diesen Addons verwenden wir nicht.",
